mapper.select:
select g.*,u.user_name as userName,u.phone,s.user_name as sendUserName,s.phone as sendPHone from gift_user g
left join tb_user u on u.user_id = g.user_id
left join tb_user s on s.user_id = g.send_user_id
where 1=1

    and g.user_id=#{userId}


    and g.send_user_id=#{sendUserId}


    and u.user_name like concat('%',#{userName},'%')


    and s.user_name like concat('%',#{sendUserName},'%')


    and u.phone = #{phone}


    and s.phone = #{sendPhone}


    and g.gift_name like concat('%',#{giftName},'%')


    and g.room_id = #{roomId}

order by g.create_time desc
